void initialize_plugin_on_io_thread(const char* mime_type) {
    // Retrieve plugin information based on MIME type
    PluginInfo* plugin_info = get_plugin_info(mime_type);
    if (!plugin_info) {
        signal_event("No plugin found for MIME type");
        return;
    }

    // Ensure execution is on the IO thread
    if (!is_current_thread_io()) {
        run_on_io_thread(initialize_plugin_on_io_thread, mime_type);
        return;
    }

    const char* plugin_path = plugin_info->path;
    PluginType type = plugin_info->type;

    if (type == PEPPER_PLUGIN) {
        open_pepper_channel(plugin_path);
    } else if (type == NPAPI_PLUGIN) {
        open_npapi_channel(plugin_path);
    }

    // Manage object reference count until the channel is opened or an error occurs
    manage_reference_count(plugin_info);
}

void initialize_plugin_on_io_thread(const std::string& mime_type) {
    // Retrieve plugin information for the specified MIME type
    PluginInfo* plugin_info = get_plugin_info_by_mime_type(mime_type);
    if (!plugin_info) {
        signal_event(EVENT_PLUGIN_NOT_FOUND);
        return;
    }

    // Retrieve plugin path
    const std::string& plugin_path = plugin_info->path;

    // Ensure this runs on the IO thread
    if (!is_current_thread_io_thread()) {
        post_task_to_io_thread(initialize_plugin_on_io_thread, mime_type);
        return;
    }

    bool is_pepper_plugin = is_pepper_plugin_type(plugin_info->type);
    if (is_pepper_plugin) {
        open_pepper_plugin_channel(plugin_path);
    } else {
        open_npapi_plugin_channel(plugin_path);
    }
}
